/* Immutable glyphs are mapped from unused Flash, never copied into heap.
 * Failure is detected before opening any Chinese UI or changing stored data. */
#include "esp_partition.h"
#include "esp_log.h"
#include "mbedtls/sha256.h"
#include <string.h>
esp_err_t feishu_font_init(void)
{
    static esp_partition_mmap_handle_t handle;
    if(font_dsc.glyph_bitmap)return ESP_OK;
    const esp_partition_t *part=esp_partition_find_first(ESP_PARTITION_TYPE_DATA,0x40,"feishu_font");
    if(!part || part->size<1814190)return ESP_ERR_NOT_FOUND;
    const void *mapped=NULL;
    esp_err_t err=esp_partition_mmap(part,0,1814190,ESP_PARTITION_MMAP_DATA,&mapped,&handle);
    if(err!=ESP_OK)return err;
    static const unsigned char expected[32]={0x86,0xee,0xc6,0xeb,0x3c,0x33,0x09,0x20,0xb8,0x56,0x15,0x56,0x3c,0x57,0x8d,0xd5,0x53,0x4b,0x61,0x9e,0xcd,0x01,0x3c,0x7d,0x93,0x08,0xb8,0xe0,0xbb,0x67,0x19,0xeb};
    unsigned char actual[32];
    if(mbedtls_sha256(mapped,1814190,actual,0) || memcmp(expected,actual,32)) {
        esp_partition_munmap(handle);return ESP_ERR_INVALID_CRC;
    }
    font_dsc.glyph_bitmap=mapped;
    ESP_LOGI("feishu_font","4bpp mapped bytes=%u hash_verified=1",(unsigned)1814190);
    return ESP_OK;
}
#endif /*#if LV_FONT_AI_PASSPORT_14*/

